/**
 * Delivery pump: dequeue → skip duplicates → process → ack + emit, or requeue
 * with backoff on failure.
 *
 * Delivery guarantees:
 * - Effectively-once: the sink is only told about a message after the
 *   downstream accepted it (processMessage returned true), and the message is
 *   acked and recorded in the dedup guard at that same moment. From then on
 *   the id can neither be dequeued again (acked) nor re-delivered (deduped),
 *   so a retry, a requeue, or a duplicate enqueue can never make the sink see
 *   an id twice — including when an earlier attempt failed after the
 *   downstream had already accepted the message.
 * - Per-key ordering: while a message is waiting for its retry backoff (or is
 *   otherwise attempted-but-unfinalized), later messages with the same key are
 *   held back and never delivered ahead of it, even across retries.
 */
import { retryWithBackoff } from './retry.js'

export function createPump({ queue, dedup, sink, clock, processMessage, maxAttempts = 3 }) {
  const retrier = retryWithBackoff(clock)
  // key -> id of the oldest message of that key that has been attempted but is
  // not finalized yet. Later same-key messages must not be delivered until it
  // finalizes (delivered, abandoned, or deduped). Only the blocker itself may
  // pass the gate, so the map never needs to hold more than one id per key.
  const awaiting = new Map()

  function hold(message) {
    if (!awaiting.has(message.key)) awaiting.set(message.key, message.id)
  }

  function unblock(message) {
    if (awaiting.get(message.key) === message.id) awaiting.delete(message.key)
  }

  return {
    run(steps = Infinity) {
      for (let i = 0; i < steps; i++) {
        const message = queue.dequeue()
        if (message === null) break
        if (message.retryAt !== undefined && clock.now() < message.retryAt) {
          // Waiting for its backoff: put it aside for now, but hold its key so
          // no later same-key message can overtake it while it waits.
          hold(message)
          queue.requeue(message)
          continue
        }
        if (dedup.isDuplicate(message.id, clock.now())) {
          queue.ack(message.id)
          unblock(message)
          continue
        }
        if (awaiting.has(message.key) && awaiting.get(message.key) !== message.id) {
          // An older message of this key has not been finalized yet; keep the
          // per-key order and give the rest of the queue a chance first.
          queue.requeue(message)
          continue
        }
        let ok = false
        try {
          ok = processMessage(message)
        } catch {
          // A crashing downstream counts as a failed attempt; the message
          // stays in the queue for a retry instead of being lost.
          ok = false
        }
        if (!ok) {
          message.attempts += 1
          if (message.attempts >= maxAttempts) {
            queue.ack(message.id)
            sink.failed(message)
            unblock(message)
            continue
          }
          message.retryAt = clock.now() + retrier.delayFor(message.attempts)
          hold(message)
          queue.requeue(message)
          continue
        }
        // The downstream accepted the message: finalize it. The id is now both
        // acked (never dequeued again) and dedup-recorded (never re-emitted),
        // so the sink records it exactly once.
        queue.ack(message.id)
        sink.emit(message)
        dedup.record(message.id, clock.now())
        unblock(message)
      }
    },
  }
}

// Scratch verification for the two delivery guarantees under failure+retry
// paths. Not part of the test suite; deleted after verification.
import assert from 'node:assert/strict'
import { createQueue, createDedup, createPump, createSink } from './src/index.js'

function autoClock() {
  let t = 0
  return { now: () => ++t, peek: () => t }
}

function setup(processMessage, { maxAttempts, clock } = {}) {
  const queue = createQueue()
  const sink = createSink()
  const dedup = createDedup({ windowMs: 1_000_000 })
  const pump = createPump({
    queue, dedup, sink,
    clock: clock ?? autoClock(),
    processMessage,
    maxAttempts: maxAttempts ?? 3,
  })
  return { queue, sink, dedup, pump }
}

const deliveredOnce = (sink, id) => sink.deliveredIds().filter((x) => x === id).length

// S1: transient failure on the older same-key message; successor must not
// overtake it across the retry, other keys may proceed.
{
  const calls = { m1: 0 }
  const { queue, sink, pump } = setup((m) => {
    if (m.id === 'm1') return ++calls.m1 > 1 // fail once, then accept
    return true
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  queue.enqueue({ id: 'm4', key: 'K9', payload: 4 })
  pump.run()
  const ids = sink.deliveredIds()
  assert.deepEqual([...new Set(ids)].sort(), ['m1', 'm2', 'm4'])
  assert.ok(ids.indexOf('m1') < ids.indexOf('m2'), 'per-key order violated')
  assert.equal(calls.m1, 2, 'm1 must be retried once after the transient failure')
  assert.equal(sink.hasDuplicate(), false)
  console.log('S1 ok:', ids)
}

// S2: retry fires within a single run once the injected clock passes retryAt.
{
  const calls = { m1: 0 }
  const { queue, sink, pump } = setup((m) => {
    if (m.id === 'm1') return ++calls.m1 > 1
    return true
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  pump.run() // clock ticks on every now() read
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
  assert.equal(sink.hasDuplicate(), false)
  console.log('S2 ok')
}

// S3: a waiting message must not starve other keys in the same run.
{
  const { queue, sink, pump, clock } = setup((m) => {
    if (m.id === 'm1') return false // always fails for now
    return true
  }, { clock: { now: () => 0 } })
  queue.enqueue({ id: 'm1', key: 'K1', payload: 1 })
  queue.enqueue({ id: 'm3', key: 'K2', payload: 3 })
  pump.run(20)
  assert.deepEqual(sink.deliveredIds(), ['m3'], 'other keys must not be blocked')
  clock.now = () => 10_000
  pump.run(20)
  assert.ok(sink.deliveredIds().includes('m1'))
  assert.equal(sink.hasDuplicate(), false)
  console.log('S3 ok')
}

// S4: exhaustion -> reported failed, never delivered; same-key successor is
// delivered only afterwards.
{
  let calls = 0
  const { queue, sink, pump, clock } = setup(() => {
    calls++
    return false
  }, { clock: { now: () => 0 } })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  for (let t = 0; t <= 3000; t += 1000) {
    clock.now = () => t
    pump.run(30)
  }
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.deepEqual(sink.deliveredIds(), ['m2'], 'm1 must never be delivered; m2 after exhaustion')
  assert.equal(calls, 3, 'exactly maxAttempts downstream attempts')
  assert.equal(sink.hasDuplicate(), false)
  console.log('S4 ok')
}

// S5: the downstream accepts the message but the attempt still reports
// failure: the sink must never record the id twice (effectively-once).
{
  const accepted = new Set()
  let calls = 0
  const { queue, sink, pump, clock } = setup((m) => {
    calls++
    accepted.add(m.id) // downstream accepted...
    return false // ...but the attempt reports failure
  }, { clock: { now: () => 0 } })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  for (let t = 0; t <= 3000; t += 1000) {
    clock.now = () => t
    pump.run(30)
  }
  assert.ok(accepted.has('m1'))
  assert.ok(deliveredOnce(sink, 'm1') <= 1, 'at most one delivery per id')
  assert.equal(sink.hasDuplicate(), false)
  assert.deepEqual(sink.failedIds(), ['m1'])
  assert.ok(calls <= 3, 'no delivery attempts beyond maxAttempts')
  console.log('S5 ok')
}

// S6: duplicate id enqueued while the first copy is failing -> exactly one
// delivery once everything settles.
{
  const calls = { m1: 0 }
  const { queue, sink, pump } = setup((m) => {
    if (m.id === 'm1') return ++calls.m1 > 1
    return true
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  pump.run()
  assert.deepEqual(sink.deliveredIds(), ['m1'])
  assert.equal(sink.hasDuplicate(), false)
  console.log('S6 ok')
}

// S7: per-key blocking persists across pump.run() calls, even 1 step at a time.
{
  const calls = { m1: 0 }
  const { queue, sink, pump, clock } = setup((m) => {
    if (m.id === 'm1') return ++calls.m1 > 1
    return true
  }, { clock: { now: () => 0 } })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  pump.run(1) // m1 fails, goes into backoff
  clock.now = () => 10_000
  pump.run(1) // dequeues m2 first: must NOT deliver it while m1 is unfinalized
  assert.deepEqual(sink.deliveredIds(), [], 'successor must wait for the older message')
  pump.run(1) // m1 retry succeeds
  pump.run(1) // m2
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
  assert.equal(sink.hasDuplicate(), false)
  console.log('S7 ok')
}

// S8: a throwing downstream counts as a failed attempt; the message survives
// and is delivered on retry, once.
{
  const calls = { m1: 0 }
  const { queue, sink, pump } = setup((m) => {
    if (m.id === 'm1') {
      calls.m1++
      if (calls.m1 === 1) throw new Error('connection reset after accept')
      return true
    }
    return true
  })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  pump.run()
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2'])
  assert.equal(calls.m1, 2)
  assert.equal(sink.hasDuplicate(), false)
  console.log('S8 ok')
}

// S9: a message born with a future retryAt holds its key until it is delivered.
{
  const { queue, sink, pump } = setup(() => true, { clock: { now: () => 0 } })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1, retryAt: 100 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  queue.enqueue({ id: 'm3', key: 'K2', payload: 3 })
  pump.run(20)
  assert.deepEqual(sink.deliveredIds(), ['m3'])
  const { queue: q2, sink: s2, pump: p2 } = setup(() => true, { clock: { now: () => 200 } })
  q2.enqueue({ id: 'm1', key: 'K', payload: 1, retryAt: 100 })
  q2.enqueue({ id: 'm2', key: 'K', payload: 2 })
  p2.run(20)
  assert.deepEqual(s2.deliveredIds(), ['m1', 'm2'])
  console.log('S9 ok')
}

// S10: several same-key messages behind a repeatedly failing head stay in
// enqueue order once things settle.
{
  const calls = { m1: 0, m2: 0 }
  const { queue, sink, pump, clock } = setup((m) => {
    if (m.id === 'm1') return ++calls.m1 > 2 // fails twice
    if (m.id === 'm2') return ++calls.m2 > 1 // fails once
    return true
  }, { clock: { now: () => 0 } })
  queue.enqueue({ id: 'm1', key: 'K', payload: 1 })
  queue.enqueue({ id: 'm2', key: 'K', payload: 2 })
  queue.enqueue({ id: 'm3', key: 'K', payload: 3 })
  for (let t = 0; t <= 5000; t += 250) {
    clock.now = () => t
    pump.run(50)
  }
  assert.deepEqual(sink.deliveredIds(), ['m1', 'm2', 'm3'])
  assert.equal(sink.hasDuplicate(), false)
  console.log('S10 ok')
}

console.log('\nAll guarantee scenarios passed.')

